struct ref_t
{
  void *label;
  void *ptr;
  unsigned count;
};

struct node
{
  int color;
  node *parent;
  node *left;
  node *right;
  ref_t *value;
};

struct result
{
  node *position;
  bool inserted;
};

struct tree
{
  node *header;
  unsigned count;
  char compare;
};

